<html lang="en">
<head>
<meta charset="utf-8"/>
<title>IMF WEO Global Growth Outlook 2024–2026 - Infographic Poster</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #002244;
    font-family: 'Helvetica Neue', Arial, sans-serif;
    width: 2384px;
    min-height: 3370px;
  }
  #poster {
    width: 2384px;
    min-height: 3370px;
    background: #f4f5f7;
    display: flex;
    flex-direction: column;
    padding: 0;
  }
  /* ── Header ── */
  #header {
    background: #002244;
    color: #fff;
    padding: 80px 120px 60px;
    display: flex;
    flex-direction: column;
    gap: 18px;
  }
  #header .venue {
    font-size: 28px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #7fafd4;
    font-weight: 400;
  }
  #header h1 {
    font-size: 96px;
    font-weight: 700;
    line-height: 1.08;
    color: #ffffff;
    max-width: 1900px;
  }
  #header .subtitle {
    font-size: 38px;
    color: #a8c4da;
    font-weight: 300;
    margin-top: 8px;
    max-width: 1700px;
    line-height: 1.4;
  }
  #header .meta-row {
    display: flex;
    gap: 60px;
    margin-top: 24px;
    align-items: center;
  }
  .kpi-pill {
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.25);
    border-radius: 8px;
    padding: 16px 32px;
    text-align: center;
  }
  .kpi-pill .kpi-val {
    font-size: 56px;
    font-weight: 700;
    color: #e8a030;
    line-height: 1;
  }
  .kpi-pill .kpi-lbl {
    font-size: 22px;
    color: #a8c4da;
    margin-top: 6px;
  }
  .risk-badge {
    background: #e8a030;
    color: #002244;
    border-radius: 8px;
    padding: 16px 40px;
    font-size: 32px;
    font-weight: 700;
    letter-spacing: 1px;
    align-self: center;
    margin-left: auto;
  }
  /* ── Section wrapper ── */
  #sections {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto auto;
    gap: 0;
    flex: 1;
    padding: 40px 60px 60px;
    background: #f4f5f7;
  }
  .section {
    background: #fff;
    border-radius: 16px;
    margin: 20px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }
  .section.full-width {
    grid-column: 1 / -1;
  }
  .section-header {
    background: #002244;
    color: #fff;
    padding: 28px 40px;
    display: flex;
    align-items: center;
    gap: 18px;
  }
  .section-number {
    background: #e8a030;
    color: #002244;
    font-weight: 700;
    font-size: 26px;
    width: 50px;
    height: 50px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .section-header h2 {
    font-size: 34px;
    font-weight: 600;
    line-height: 1.2;
  }
  .section-body {
    flex: 1;
    min-height: 480px;
  }
  .section-body .infographic-container {
    width: 100%;
    height: 100%;
    min-height: 480px;
  }
  /* ── Footer ── */
  #footer {
    background: #002244;
    color: #7fafd4;
    padding: 30px 120px;
    font-size: 22px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  #footer .sources {
    font-size: 20px;
    line-height: 1.6;
  }
  #footer .date {
    color: #a8c4da;
    font-size: 24px;
  }
</style>
</head>
<body>
<div id="poster">

  <!-- ══ HEADER ══ -->
  <div id="header">
    <div class="venue">IMF–World Bank Annual Meetings Research Symposium</div>
    <h1>Global Economy in the Shadow of War</h1>
    <div class="subtitle">IMF World Economic Outlook Trends 2024–2026 &mdash; Synthesis of Eight Editions</div>
    <div class="meta-row">
      <div class="kpi-pill">
        <div class="kpi-val">3.0–3.3%</div>
        <div class="kpi-lbl">Global Growth Band</div>
      </div>
      <div class="kpi-pill">
        <div class="kpi-val">~3.8%</div>
        <div class="kpi-lbl">Pre-Pandemic Average</div>
      </div>
      <div class="kpi-pill">
        <div class="kpi-val">8</div>
        <div class="kpi-lbl">WEO Editions Reviewed</div>
      </div>
      <div class="risk-badge">⚠ Risk Balance: TILTED TO THE DOWNSIDE — All Editions</div>
    </div>
  </div>

  <!-- ══ SECTIONS ══ -->
  <div id="sections">

    <!-- § 1 Growth Trajectory — full width -->
    <div class="section full-width" id="sec1">
      <div class="section-header">
        <div class="section-number">1</div>
        <h2>Global Growth Projections: A Narrow Band of Mediocrity (Jul 2024 – Apr 2026)</h2>
      </div>
      <div class="section-body" style="min-height:560px;">
        <div id="chart-growth" style="width:100%;height:560px;"></div>
      </div>
    </div>

    <!-- § 2 Downside Risks -->
    <div class="section" id="sec2">
      <div class="section-header">
        <div class="section-number">2</div>
        <h2>Dominant Downside Risks</h2>
      </div>
      <div class="section-body" style="min-height:580px;">
        <div id="chart-risks" style="width:100%;height:580px;"></div>
      </div>
    </div>

    <!-- § 3 Inflation & Monetary Policy -->
    <div class="section" id="sec3">
      <div class="section-header">
        <div class="section-number">3</div>
        <h2>Inflation Outlook &amp; Monetary Policy</h2>
      </div>
      <div class="section-body" style="min-height:580px;">
        <div id="chart-inflation" style="width:100%;height:580px;"></div>
      </div>
    </div>

    <!-- § 4 Policy Evolution — full width -->
    <div class="section full-width" id="sec4">
      <div class="section-header">
        <div class="section-number">4</div>
        <h2>Evolving IMF Policy Priorities: From Monetary Pivot to Defense-Spending Trade-offs</h2>
      </div>
      <div class="section-body" style="min-height:520px;">
        <div id="chart-policy" style="width:100%;height:520px;"></div>
      </div>
    </div>

    <!-- § 5 Special Themes — full width -->
    <div class="section full-width" id="sec5">
      <div class="section-header">
        <div class="section-number">5</div>
        <h2>Special Analytical Themes Across WEO Editions</h2>
      </div>
      <div class="section-body" style="min-height:460px;">
        <div id="chart-themes" style="width:100%;height:460px;"></div>
      </div>
    </div>

  </div><!-- /sections -->

  <!-- ══ FOOTER ══ -->
  <div id="footer">
    <div class="sources">
      Sources: IMF World Economic Outlook, July 2024 – April 2026 (eight editions). All growth figures are calendar-year projections at time of publication.
    </div>
    <div class="date">April 2026</div>
  </div>

</div><!-- /poster -->

<script src="/app/vendor/infographic.min.js"></script>
<script>
// ── §1 Growth Trajectory line chart ──────────────────────────────────────────
const ig1 = new AntVInfographic.Infographic({
  container: '#chart-growth',
  width: '100%',
  height: '100%',
});
ig1.render(`infographic chart-line-plain-text
data
  title IMF Global Growth Projections vs Pre-Pandemic Average (%)
  desc Gray band shows the 3.0–3.3% range; dashed line marks ~3.8% pre-pandemic average
  values
    - label Jul 2024
      value 3.2
    - label Oct 2024
      value 3.2
    - label Jan 2025
      value 3.3
    - label Apr 2025
      value 3.1
    - label Jul 2025
      value 3.0
    - label Oct 2025
      value 3.0
    - label Jan 2026
      value 3.3
    - label Apr 2026
      value 3.1
theme
  palette #002244 #e8a030 #7fafd4`);

// ── §2 Downside Risks list ────────────────────────────────────────────────────
const ig2 = new AntVInfographic.Infographic({
  container: '#chart-risks',
  width: '100%',
  height: '100%',
});
ig2.render(`infographic list-waterfall-compact-card
data
  title Recurring Downside Risks — All 8 WEO Editions
  desc Balance of risks consistently tilted to the downside across every edition reviewed
  lists
    - label Trade Policy Escalation
      desc Tariff increases and retaliatory measures; front-loading masks near-term damage
      icon arrow up circle
    - label Geopolitical Tensions
      desc Middle East conflict, broader security fractures, and the shadow of war
      icon globe
    - label Technology Re-evaluation
      desc Correction risk if AI/tech investment expectations overshoot fundamentals
      icon cpu
    - label Persistent Services Inflation
      desc US inflation returning to target more slowly than peer economies
      icon chart line up
theme
  palette #e8a030 #c97a20 #a85f10 #8b4510`);

// ── §3 Inflation & Monetary Policy sequence ───────────────────────────────────
const ig3 = new AntVInfographic.Infographic({
  container: '#chart-inflation',
  width: '100%',
  height: '100%',
});
ig3.render(`infographic compare-binary-horizontal-badge-card-arrow
data
  title Inflation Trajectory: Global vs United States
  compares
    - label Global Trend
      children
        - label Declining trajectory
          desc Headline inflation falling steadily through 2026; policy pivot enabled
          icon trending down
        - label Policy Pivot (Oct 2024)
          desc Central banks began easing; space created by falling inflation
          icon arrow circle left
        - label Services Inflation Sticky
          desc Stickier globally, slowing complete disinflation
          icon alert circle
    - label United States Exception
      children
        - label Above Target Longer
          desc US inflation projected to remain above target past peer economies
          icon clock
        - label Renewed Pressure (Apr 2026)
          desc Defense spending and supply disruptions add fresh inflationary push
          icon warning
        - label Gradual Convergence
          desc Path back to target slower; monetary easing constrained
          icon arrow right
theme
  palette #002244 #7fafd4 #e8a030`);

// ── §4 Policy Evolution timeline ──────────────────────────────────────────────
const ig4 = new AntVInfographic.Infographic({
  container: '#chart-policy',
  width: '100%',
  height: '100%',
});
ig4.render(`infographic sequence-roadmap-vertical-simple
data
  title IMF Policy Priority Evolution: Mid-2024 to Early 2026
  sequences
    - label Mid-2024
      desc Manage disinflation carefully; begin monetary easing; avoid premature loosening
    - label Late 2024
      desc Policy pivot: ease monetary conditions; ensure fiscal sustainability
    - label Early 2025
      desc Rebuild fiscal buffers; address demographic gaps and gender disparities
    - label Mid-2025
      desc Restore confidence amid tariff uncertainty; structural reforms for resilience
    - label Late 2025
      desc Strengthen policy frameworks; exercise caution on industrial policy
    - label Early 2026
      desc Agile policy responses; manage defense-spending trade-offs; lay recovery foundations
theme
  palette #002244 #1a4b7a #2d6fa8 #4a8fc0 #6bacd4 #e8a030`);

// ── §5 Special Themes grid ────────────────────────────────────────────────────
const ig5 = new AntVInfographic.Infographic({
  container: '#chart-themes',
  width: '100%',
  height: '100%',
});
ig5.render(`infographic list-grid-badge-card
data
  title Special Analytical Themes Across WEO Editions
  desc Reflecting the IMF's broadening lens beyond traditional macroeconomic stabilization
  lists
    - label Monetary Policy & Disinflation
      desc Role of monetary transmission in global inflation decline
      icon bank
    - label Industrial Policy Effectiveness
      desc Fiscal costs vs. strategic benefits of industrial subsidies
      icon factory
    - label Social Acceptability of Reforms
      desc Political economy constraints on structural adjustment
      icon people
    - label Demographic Challenges
      desc Aging populations and long-run fiscal pressures
      icon person
    - label Gender & Labor Markets
      desc Reducing gender gaps to lift potential growth
      icon star
    - label Migration & Skills Alignment
      desc Matching migrant skills to host-country labor needs
      icon map
theme
  palette #002244 #1a4b7a #2d6fa8 #4a8fc0 #6bacd4 #e8a030`);
</script>
</body>
</html>
